const BODY_SEGS: [string, string, string][] = [
  ["pelvis", "c7t1", "torso"], ["shoulderR", "shoulderL", "shoulders"],
  ["hipR", "hipL", "hips"], ["c7t1", "headCenter", "neck"], ["headCenter", "headTop", "head"],
  ["shoulderR", "elbowR", "uaR"], ["elbowR", "wristR", "faR"], ["wristR", "handR", "hdR"],
  ["shoulderL", "elbowL", "uaL"], ["elbowL", "wristL", "faL"], ["wristL", "handL", "hdL"],
  ["hipR", "kneeR", "thR"], ["kneeR", "ankleR", "shR"], ["ankleR", "footR", "ftR"],
  ["hipL", "kneeL", "thL"], ["kneeL", "ankleL", "shL"], ["ankleL", "footL", "ftL"],
];

const SPHERE_MARKS = [
  "headCenter", "handR", "handL", "shoulderR", "shoulderL",
  "elbowR", "elbowL", "wristR", "wristL", "hipR", "hipL",
  "kneeR", "kneeL", "ankleR", "ankleL",
];

const RADII: Record<string, number> = {
  torso: 0.065, shoulders: 0.03, hips: 0.045, neck: 0.028, head: 0.058,
  uaR: 0.024, faR: 0.019, hdR: 0.022, uaL: 0.024, faL: 0.019, hdL: 0.022,
  thR: 0.042, shR: 0.028, ftR: 0.02, thL: 0.042, shL: 0.028, ftL: 0.02,
};

interface Fighter {
  group: THREE.Group;
  links: Record<string, THREE.Mesh>;
  spheres: Record<string, THREE.Mesh>;
}

function buildFighter(skinColor: number, shortsColor: number): Fighter {
  const group = new THREE.Group();
  const links: Record<string, THREE.Mesh> = {};
  const spheres: Record<string, THREE.Mesh> = {};
  const mat = (c: number) => new THREE.MeshPhongMaterial({ color: c, shininess: 30, specular: 0x222222 });

  for (const [, , name] of BODY_SEGS) {
    const r = RADII[name] || 0.02;
    const c = name.includes("th") || name.includes("hip") ? shortsColor : skinColor;
    const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 1, 8), mat(c));
    m.castShadow = true;
    group.add(m);
    links[name] = m;
  }

  for (const mk of SPHERE_MARKS) {
    const r = mk.includes("head") ? 0.06
      : mk.includes("hand") ? 0.022
      : mk.includes("shoulder") ? 0.025
      : mk.includes("hip") ? 0.03
      : mk.includes("knee") ? 0.025
      : mk.includes("ankle") ? 0.022
      : 0.018;
    const c = mk.includes("hip") || mk.includes("knee") ? shortsColor : skinColor;
    const m = new THREE.Mesh(new THREE.SphereGeometry(r, 10, 10), mat(c));
    m.castShadow = true;
    group.add(m);
    spheres[mk] = m;
  }

  return { group, links, spheres };
}

function updateFighter(fighter: Fighter, landmarks: Landmarks): void {
  const v1 = new THREE.Vector3();
  const v2 = new THREE.Vector3();
  const up = new THREE.Vector3(0, 1, 0);

  for (const [from, to, name] of BODY_SEGS) {
    const m = fighter.links[name];
    const p1 = landmarks[from];
    const p2 = landmarks[to];
    if (!p1 || !p2) continue;
    v1.copy(p1);
    v2.copy(p2);
    const mid = v1.clone().add(v2).multiplyScalar(0.5);
    const dir = v2.clone().sub(v1);
    const len = dir.length();
    m.position.copy(mid);
    m.scale.y = len;
    if (len > 0.001) {
      dir.normalize();
      const q = new THREE.Quaternion();
      q.setFromUnitVectors(up, dir);
      m.quaternion.copy(q);
    }
  }

  for (const mk of SPHERE_MARKS) {
    if (landmarks[mk]) fighter.spheres[mk].position.copy(landmarks[mk]);
  }
}

