// SCENE SETUP
// ═══════════════════════════════════════════════════════════════════════

export interface SceneHandle {
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  renderer: THREE.WebGLRenderer;
  fighterA: Fighter;
  fighterB: Fighter;
  flashMesh: THREE.Mesh;
  rootA: THREE.Vector3;
  rootB: THREE.Vector3;
}

export function createScene(container: HTMLElement): SceneHandle {
  const W = container.clientWidth;
  const H = container.clientHeight;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x08080e);
  scene.fog = new THREE.Fog(0x08080e, 7, 16);

  const camera = new THREE.PerspectiveCamera(46, W / H, 0.1, 50);
  camera.position.set(0, 1.2, 3.6);
  camera.lookAt(0, 0.9, 0);

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(W, H);
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  container.appendChild(renderer.domElement);

  // Lights
  scene.add(new THREE.AmbientLight(0x334466, 0.6));

  const kl = new THREE.DirectionalLight(0xffeedd, 1.0);
  kl.position.set(3, 5, 4);
  kl.castShadow = true;
  kl.shadow.mapSize.set(1024, 1024);
  kl.shadow.camera.near = 0.5;
  kl.shadow.camera.far = 15;
  kl.shadow.camera.left = -3;
  kl.shadow.camera.right = 3;
  kl.shadow.camera.top = 3;
  kl.shadow.camera.bottom = -1;
  scene.add(kl);

  const fl = new THREE.DirectionalLight(0x4466aa, 0.4);
  fl.position.set(-2, 3, -2);
  scene.add(fl);

  const rl = new THREE.DirectionalLight(0xff6644, 0.3);
  rl.position.set(0, 2, -4);
  scene.add(rl);

  // Ground
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(14, 14),
    new THREE.MeshPhongMaterial({ color: 0x14141e, shininess: 60, specular: 0x222233 }),
  );
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  const grid = new THREE.GridHelper(8, 16, 0x222244, 0x161628);
  grid.position.set(0, 0.002, 0);
  scene.add(grid);

  // Ring posts
  const pm = new THREE.MeshPhongMaterial({ color: 0x888888 });
  for (const [x, , z] of [[-2.5, 0, -2.5], [2.5, 0, -2.5], [-2.5, 0, 2.5], [2.5, 0, 2.5]] as [number, number, number][]) {
    const p = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 1.6, 6), pm);
    p.position.set(x, 0.8, z);
    p.castShadow = true;
    scene.add(p);
  }

  // Ring ropes
  const rm = new THREE.MeshBasicMaterial({ color: 0x444466 });
  for (const ry of [0.5, 0.9, 1.3]) {
    const pts: [number, number, number][] = [[-2.5, 0, -2.5], [2.5, 0, -2.5], [2.5, 0, 2.5], [-2.5, 0, 2.5]];
    for (let i = 0; i < 4; i++) {
      const [x1, , z1] = pts[i];
      const [x2, , z2] = pts[(i + 1) % 4];
      const d = new THREE.Vector3(x2 - x1, 0, z2 - z1);
      const l = d.length();
      const rope = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, l, 4), rm);
      rope.position.set((x1 + x2) / 2, ry, (z1 + z2) / 2);
      const q = new THREE.Quaternion();
      q.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize());
      rope.quaternion.copy(q);
      scene.add(rope);
    }
  }

  // Fighters
  const fighterA = buildFighter(0xd4a574, 0x1a3a6b);
  const fighterB = buildFighter(0xc49060, 0x6b1a1a);
  scene.add(fighterA.group);
  scene.add(fighterB.group);

  // Flash effect
  const flashMesh = new THREE.Mesh(
    new THREE.SphereGeometry(0.1, 16, 16),
    new THREE.MeshBasicMaterial({ color: 0xffffcc, transparent: true, opacity: 0 }),
  );
  scene.add(flashMesh);

  const rootA = new THREE.Vector3(-0.5, 0.95, 0);
  const rootB = new THREE.Vector3(0.5, 0.95, 0);

  return { scene, camera, renderer, fighterA, fighterB, flashMesh, rootA, rootB };
}

export function disposeScene(container: HTMLElement, handle: SceneHandle): void {
  handle.renderer.dispose();
  if (container.contains(handle.renderer.domElement)) {
    container.removeChild(handle.renderer.domElement);
  }
}

export function handleResize(handle: SceneHandle, container: HTMLElement): void {
  const w = container.clientWidth;
  const h = container.clientHeight;
  handle.camera.aspect = w / h;
  handle.camera.updateProjectionMatrix();
  handle.renderer.setSize(w, h);
}

// ═══════════════════════════════════════════════════════════════════════
// ANIMATION TICK
// ═══════════════════════════════════════════════════════════════════════

export interface AnimState {
  anglesA: JointAngles;
  anglesB: JointAngles;
  targetA: JointAngles;
  targetB: JointAngles;
  fromA: JointAngles;
  fromB: JointAngles;
  blend: number;
  flashAlpha: number;
  flashSide: "a" | "b" | null;
}

export function tick(
  handle: SceneHandle,
  anim: AnimState,
  dt: number,
  ts: number,
): { anglesA: JointAngles; anglesB: JointAngles } {
  if (anim.blend < 1) {
    anim.blend = Math.min(1, anim.blend + dt * 2.5);
    const t = smoothstep(anim.blend);
    anim.anglesA = lerpAngles(anim.fromA, anim.targetA, t);
    anim.anglesB = lerpAngles(anim.fromB, anim.targetB, t);
  }

  const rA = solveFK(handle.rootA, 0, anim.anglesA);
  const rB = solveFK(handle.rootB, Math.PI, anim.anglesB);
  updateFighter(handle.fighterA, rA.landmarks);
  updateFighter(handle.fighterB, rB.landmarks);

  if (anim.flashAlpha > 0) {
    anim.flashAlpha = Math.max(0, anim.flashAlpha - dt * 3);
    (handle.flashMesh.material as THREE.MeshBasicMaterial).opacity = anim.flashAlpha;
    handle.flashMesh.scale.setScalar(1 + (1 - anim.flashAlpha) * 2.5);
    const target = anim.flashSide === "a" ? rA.landmarks.headCenter : rB.landmarks.headCenter;
    if (target) handle.flashMesh.position.copy(target);
  }

  handle.camera.position.y = 1.2 + Math.sin(ts * 0.002) * 0.003;
  handle.renderer.render(handle.scene, handle.camera);

  return { anglesA: anim.anglesA, anglesB: anim.anglesB };
}

// ═══════════════════════════════════════════════════════════════════════
// REACT HOOK — useScene
// ═══════════════════════════════════════════════════════════════════════

export function useScene(
  mountRef: React.RefObject<HTMLDivElement | null>,
  animRef: React.MutableRefObject<AnimState>,
  onAnglesUpdate: (anglesA: JointAngles, anglesB: JointAngles) => void,
): void {
  useEffect(() => {
    const ct = mountRef.current;
    if (!ct) return;

    const handle = createScene(ct);

    // Initial FK
    const initAngles = animRef.current.anglesA;
    const rA = solveFK(handle.rootA, 0, initAngles);
    const rB = solveFK(handle.rootB, Math.PI, initAngles);
    updateFighter(handle.fighterA, rA.landmarks);
    updateFighter(handle.fighterB, rB.landmarks);

    let lastT = 0;
    let rafId: number;

    function loop(ts: number) {
      rafId = requestAnimationFrame(loop);
      const dt = Math.min((ts - lastT) / 1000, 0.05);
      lastT = ts;

      const result = tick(handle, animRef.current, dt, ts);

      // Throttled angle display update (~5 Hz)
      if (Math.floor(ts / 200) !== Math.floor((ts - dt * 1000) / 200)) {
        onAnglesUpdate(result.anglesA, result.anglesB);
      }
    }

    rafId = requestAnimationFrame(loop);

    const onResize = () => handleResize(handle, ct);
    window.addEventListener("resize", onResize);

    return () => {
      cancelAnimationFrame(rafId);
      window.removeEventListener("resize", onResize);
      disposeScene(ct, handle);
    };
  }, []);
}

