// UI COMPONENTS (pure presentational)
// ═══════════════════════════════════════════════════════════════════════

interface JointRowProps {
  name: string;
  angles: { fe?: number; aa?: number; ie?: number } | undefined;
}

export function JointRow({ name, angles }: JointRowProps) {
  if (!angles) return null;
  const j = JOINTS[name];
  if (!j) return null;

  return (
    <div style={{ display: "flex", gap: 4, fontSize: 8, alignItems: "center", marginBottom: 1 }}>
      <span style={{ width: 64, color: "#667799", textAlign: "right" }}>{name}</span>
      {(["fe", "aa", "ie"] as const).map((d) => {
        if (!j.rom[d]) return null;
        const v = Math.round(angles[d] || 0);
        const pct = ((v - j.rom[d][0]) / (j.rom[d][1] - j.rom[d][0])) * 100;
        return (
          <div key={d} style={{ width: 48, display: "flex", flexDirection: "column", alignItems: "center" }}>
            <div style={{ width: "100%", height: 3, background: "rgba(60,70,100,.3)", borderRadius: 1, position: "relative" }}>
              <div style={{
                position: "absolute", height: "100%", borderRadius: 1,
                background: d === "fe" ? "#4488cc" : d === "aa" ? "#44aa66" : "#cc8833",
                width: `${Math.max(2, Math.min(100, pct))}%`,
              }} />
            </div>
            <span style={{ color: "#556677" }}>{v}°</span>
          </div>
        );
      })}
    </div>
  );
}

interface FighterPanelProps {
  side: "A" | "B";
  hp: number;
  stamina: number;
  action: string | null;
  reasoning: string;
  actionSchema: string | undefined;
}

export function FighterPanel({ side, hp, stamina, action, reasoning, actionSchema }: FighterPanelProps) {
  const isA = side === "A";
  const accent = isA ? "#3a7bd5" : "#d53a3a";
  const border = isA ? "rgba(58,123,213,.2)" : "rgba(213,58,58,.2)";
  const hpLabel = isA ? "#88aacc" : "#cc8888";
  const staColor = isA ? "#3388cc" : "#cc5533";
  const reasonColor = isA ? "#556688" : "#776655";
  const schemaColor = isA ? "#445566" : "#554444";
  const schemaBorder = isA ? "rgba(60,80,120,.15)" : "rgba(120,60,60,.15)";

  return (
    <div style={{
      position: "absolute", top: 42, [isA ? "left" : "right"]: 6, zIndex: 10,
      background: "rgba(8,8,14,.9)", border: `1px solid ${border}`,
      borderRadius: 8, padding: "6px 10px", backdropFilter: "blur(8px)",
      width: 172, textAlign: isA ? undefined : "right",
    }}>
      <div style={{ fontSize: 10, fontWeight: 700, color: accent, letterSpacing: 1, marginBottom: 3 }}>FIGHTER {side}</div>
      <div style={{ marginBottom: 2 }}>
        <div style={{ display: "flex", justifyContent: "space-between", fontSize: 8, color: hpLabel }}><span>HP</span><span>{hp}</span></div>
        <div style={{ height: 5, background: "rgba(60,70,100,.3)", borderRadius: 2, overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${hp}%`, background: hp > 50 ? "#22aa55" : hp > 25 ? "#cc8822" : "#cc3333", borderRadius: 2, transition: "width .5s" }} />
        </div>
      </div>
      <div style={{ marginBottom: 3 }}>
        <div style={{ display: "flex", justifyContent: "space-between", fontSize: 8, color: hpLabel }}><span>STA</span><span>{stamina}</span></div>
        <div style={{ height: 3, background: "rgba(60,70,100,.3)", borderRadius: 1, overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${stamina}%`, background: staColor, borderRadius: 1, transition: "width .5s" }} />
        </div>
      </div>
      {action && (
        <div style={{ fontSize: 9 }}>
          <span style={{ color: accent, fontWeight: 700 }}>{action.toUpperCase()}</span>
          {reasoning && <div style={{ fontSize: 8, color: reasonColor, fontStyle: "italic" }}>"{reasoning}"</div>}
        </div>
      )}
      {action && actionSchema && (
        <div style={{ fontSize: 7, color: schemaColor, marginTop: 2, lineHeight: 1.4, borderTop: `1px solid ${schemaBorder}`, paddingTop: 2 }}>
          {actionSchema.slice(0, 120)}
        </div>
      )}
    </div>
  );
}

interface NarrativeOverlayProps {
  lastLog: { narr: string; dA: number; dB: number; out?: string } | undefined;
  phase: string;
}

export function NarrativeOverlay({ lastLog, phase }: NarrativeOverlayProps) {
  if (!lastLog) return null;
  const borderColor = lastLog.out?.includes("a_wins") ? "rgba(58,123,213,.3)"
    : lastLog.out?.includes("b_wins") ? "rgba(213,58,58,.3)"
    : "rgba(100,120,180,.2)";

  return (
    <div style={{
      position: "absolute", top: "50%", left: "50%", transform: "translate(-50%,-50%)", zIndex: 10,
      background: "rgba(8,8,14,.92)", border: `1px solid ${borderColor}`,
      borderRadius: 8, padding: "6px 16px", maxWidth: 360, textAlign: "center",
      pointerEvents: "none", opacity: phase === "animating" ? 1 : 0.12, transition: "opacity .5s",
    }}>
      <div style={{ fontSize: 10, color: "#c8ccd4", lineHeight: 1.4 }}>{lastLog.narr}</div>
      <div style={{ fontSize: 8, color: "#556688", marginTop: 2 }}>
        {lastLog.dA > 0 && <span style={{ color: "#cc4444" }}>A:-{lastLog.dA}hp </span>}
        {lastLog.dB > 0 && <span style={{ color: "#4488cc" }}>B:-{lastLog.dB}hp </span>}
      </div>
    </div>
  );
}

interface WinnerBannerProps {
  winner: string | null;
}

export function WinnerBanner({ winner }: WinnerBannerProps) {
  if (!winner) return null;
  const color = winner === "A" ? "#3a7bd5" : winner === "B" ? "#d53a3a" : "#888";
  return (
    <div style={{ position: "absolute", top: "36%", left: "50%", transform: "translate(-50%,-50%)", zIndex: 20, textAlign: "center" }}>
      <div style={{ fontSize: 26, fontWeight: 800, letterSpacing: 4, color, textShadow: "0 0 30px rgba(100,100,200,.4)" }}>
        {winner === "DRAW" ? "DRAW" : `FIGHTER ${winner} WINS`}
      </div>
    </div>
  );
}

interface JointAnglePanelProps {
  visible: boolean;
  anglesA: JointAngles;
  anglesB: JointAngles;
}

export function JointAnglePanel({ visible, anglesA, anglesB }: JointAnglePanelProps) {
  if (!visible) return null;
  const header = (side: "A" | "B") => (
    <div style={{ fontSize: 7, color: side === "A" ? "#445566" : "#554444", marginBottom: 2, display: "flex", gap: 4, justifyContent: "flex-end", paddingRight: 4 }}>
      <span style={{ width: 48, textAlign: "center", color: "#4488cc" }}>F/E</span>
      <span style={{ width: 48, textAlign: "center", color: "#44aa66" }}>Ab/Ad</span>
      <span style={{ width: 48, textAlign: "center", color: "#cc8833" }}>I/E</span>
    </div>
  );

  return (
    <div style={{ position: "absolute", top: 42, left: "50%", transform: "translateX(-50%)", zIndex: 15, display: "flex", gap: 8 }}>
      <div style={{ background: "rgba(4,4,8,.95)", border: "1px solid rgba(58,123,213,.2)", borderRadius: 6, padding: 6, width: 200 }}>
        <div style={{ fontSize: 8, color: "#3a7bd5", fontWeight: 700, marginBottom: 3, letterSpacing: 1 }}>FIGHTER A — JOINT ANGLES</div>
        {header("A")}
        {Object.keys(JOINTS).map((jn) => <JointRow key={jn} name={jn} angles={anglesA[jn]} />)}
      </div>
      <div style={{ background: "rgba(4,4,8,.95)", border: "1px solid rgba(213,58,58,.2)", borderRadius: 6, padding: 6, width: 200 }}>
        <div style={{ fontSize: 8, color: "#d53a3a", fontWeight: 700, marginBottom: 3, letterSpacing: 1 }}>FIGHTER B — JOINT ANGLES</div>
        {header("B")}
        {Object.keys(JOINTS).map((jn) => <JointRow key={jn} name={jn} angles={anglesB[jn]} />)}
      </div>
    </div>
  );
}

interface DebugPanelProps {
  visible: boolean;
  entries: { t: string; m: string; l: string }[];
  dbRef: React.RefObject<HTMLDivElement | null>;
}

const LOG_COLORS: Record<string, string> = { info: "#556688", ok: "#44aa66", warn: "#ccaa33", error: "#cc4444" };

export function DebugPanel({ visible, entries, dbRef }: DebugPanelProps) {
  if (!visible) return null;
  return (
    <div style={{ position: "absolute", bottom: 110, left: 6, zIndex: 15, width: 320 }}>
      <div ref={dbRef} style={{ background: "rgba(2,2,6,.97)", border: "1px solid rgba(100,120,180,.15)", borderRadius: 6, padding: 4, maxHeight: 140, overflowY: "auto", fontSize: 8, lineHeight: 1.5 }}>
        {entries.length === 0
          ? <div style={{ color: "#334455", textAlign: "center", padding: 4 }}>Press EXCHANGE to start</div>
          : entries.map((d, i) => (
            <div key={i} style={{ color: LOG_COLORS[d.l], borderBottom: "1px solid rgba(50,60,80,.1)", wordBreak: "break-all" }}>
              <span style={{ color: "#2a3344" }}>{d.t}</span> {d.m}
            </div>
          ))}
      </div>
    </div>
  );
}

interface TitleBarProps {
  round: number;
  exchange: number;
  phase: string;
}

export function TitleBar({ round, exchange, phase }: TitleBarProps) {
  const totalDofs = Object.keys(JOINTS).reduce((a, k) => {
    const j = JOINTS[k];
    return a + (j.rom.fe ? 1 : 0) + (j.rom.aa ? 1 : 0) + (j.rom.ie ? 1 : 0);
  }, 0);
  const phaseColor = phase === "thinking" ? "#ccaa33" : phase === "animating" ? "#44aa66" : phase === "finished" ? "#cc4444" : "#556688";

  return (
    <div style={{ position: "absolute", top: 8, left: "50%", transform: "translateX(-50%)", zIndex: 10, textAlign: "center" }}>
      <div style={{ fontSize: 9, letterSpacing: 3, textTransform: "uppercase", color: "#556688" }}>FK-Driven AI Fight — Schema v3 Joint Angles</div>
      <div style={{ fontSize: 8, color: "#3a5577", marginTop: 2 }}>
        Rd{round}/3 Ex{exchange}/12{" "}
        <span style={{ color: phaseColor, fontWeight: 700 }}>{phase.toUpperCase()}</span>
        {" "}· 14 joints · {totalDofs} DOFs · ROM-clamped
      </div>
    </div>
  );
}

interface ControlBarProps {
  phase: string;
  apiKey: string;
  auto: boolean;
  speed: string;
  showJoints: boolean;
  showDebug: boolean;
  debugErrorCount: number;
  log: { ex: number; aA: string; aB: string; narr: string }[];
  onExchange: () => void;
  onToggleAuto: () => void;
  onSetSpeed: (s: string) => void;
  onToggleJoints: () => void;
  onToggleDebug: () => void;
  onApiKeyChange: (key: string) => void;
  onReset: () => void;
}

export function ControlBar({
  phase, apiKey, auto, speed, showJoints, showDebug, debugErrorCount, log,
  onExchange, onToggleAuto, onSetSpeed, onToggleJoints, onToggleDebug, onApiKeyChange, onReset,
}: ControlBarProps) {
  return (
    <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, zIndex: 10, background: "rgba(8,8,14,.94)", borderTop: "1px solid rgba(100,120,180,.15)", padding: "6px 10px" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
        <button onClick={onExchange} disabled={phase !== "idle" || !apiKey} style={{
          background: phase === "thinking" ? "rgba(200,170,50,.15)" : "rgba(58,123,213,.15)",
          border: `1px solid ${phase === "thinking" ? "rgba(200,170,50,.3)" : "rgba(58,123,213,.3)"}`,
          color: phase === "thinking" ? "#ccaa33" : !apiKey ? "#556677" : "#88bbdd",
          borderRadius: 6, padding: "5px 12px", cursor: phase === "idle" && apiKey ? "pointer" : "wait",
          fontSize: 10, fontFamily: "inherit",
        }}>
          {phase === "thinking" ? "⧖ THINKING" : phase === "animating" ? "⚡ RESOLVING" : !apiKey ? "🔑 SET KEY" : "⚡ EXCHANGE"}
        </button>

        <button onClick={onToggleAuto} disabled={phase === "finished"} style={{
          background: auto ? "rgba(50,180,80,.15)" : "none",
          border: `1px solid ${auto ? "rgba(50,180,80,.3)" : "rgba(100,120,180,.2)"}`,
          color: auto ? "#66cc88" : "#88aabb",
          borderRadius: 6, padding: "5px 10px", cursor: "pointer", fontSize: 10, fontFamily: "inherit",
        }}>
          {auto ? "■ STOP" : "▶ AUTO"}
        </button>

        <div style={{ display: "flex", gap: 3 }}>
          {([["normal", "1×"], ["fast", "2×"], ["blitz", "4×"]] as const).map(([v, l]) => (
            <button key={v} onClick={() => onSetSpeed(v)} style={{
              background: speed === v ? "rgba(60,100,180,.2)" : "none",
              border: "1px solid rgba(100,120,180,.15)",
              color: speed === v ? "#88bbdd" : "#556677",
              borderRadius: 4, padding: "2px 6px", cursor: "pointer", fontSize: 8, fontFamily: "inherit",
            }}>{l}</button>
          ))}
        </div>

        <button onClick={onToggleJoints} style={{
          background: showJoints ? "rgba(100,100,200,.15)" : "none",
          border: "1px solid rgba(100,120,180,.2)", color: showJoints ? "#8899cc" : "#556677",
          borderRadius: 6, padding: "5px 8px", cursor: "pointer", fontSize: 8, fontFamily: "inherit",
        }}>
          {showJoints ? "HIDE" : "SHOW"} JOINTS
        </button>

        <button onClick={onToggleDebug} style={{
          background: showDebug ? "rgba(100,100,200,.15)" : "none",
          border: "1px solid rgba(100,120,180,.2)", color: showDebug ? "#8899cc" : "#556677",
          borderRadius: 6, padding: "5px 8px", cursor: "pointer", fontSize: 8, fontFamily: "inherit",
        }}>
          DEBUG{debugErrorCount > 0 ? ` (${debugErrorCount}err)` : ""}
        </button>

        <input
          type="password" placeholder="sk-ant-… API key" value={apiKey}
          onChange={(e) => onApiKeyChange(e.target.value)}
          style={{
            background: "rgba(20,20,30,.8)",
            border: `1px solid ${apiKey ? "rgba(50,180,80,.3)" : "rgba(180,80,80,.3)"}`,
            color: "#88aabb", borderRadius: 4, padding: "4px 8px",
            fontSize: 9, fontFamily: "inherit", width: 140, marginLeft: "auto",
          }}
        />

        <button onClick={onReset} style={{
          background: "none", border: "1px solid rgba(180,80,80,.2)", color: "#aa6666",
          borderRadius: 6, padding: "5px 10px", cursor: "pointer", fontSize: 10, fontFamily: "inherit",
        }}>
          ↺ RESET
        </button>
      </div>

      {log.length > 0 && (
        <div style={{ marginTop: 4, maxHeight: 52, overflowY: "auto", fontSize: 8, lineHeight: 1.4 }}>
          {log.slice(-4).map((l, i) => (
            <div key={i} style={{ color: "#667799", borderBottom: "1px solid rgba(100,120,180,.06)" }}>
              <span style={{ color: "#445566" }}>#{l.ex}</span>{" "}
              <span style={{ color: "#3a7bd5" }}>A:{l.aA}</span> vs{" "}
              <span style={{ color: "#d53a3a" }}>B:{l.aB}</span>{" "}
              <span style={{ color: "#88aacc" }}>→ {l.narr}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
